def get_rank_art(rank_name_en: str) -> bytes | None:
    """Return the raw JPEG bytes for a rank, or None if no art exists."""
    b64 = RANK_ART.get(rank_name_en)
    if b64 is None:
        return None
    import base64
    # b64 may be stored as a tuple of string chunks (for line-length)
    if isinstance(b64, tuple):
        b64 = "".join(b64)
    return base64.b64decode(b64)